INSERT INTO faqs (question, answer, sort_order, created_at, updated_at) VALUES ('What is Scouts Emergency Response (SER)?', 'Scouts Emergency Response (SER) is a youth led initiative that equips young people and communities with essential lifesaving skills, strengthening preparedness and resilience during emergencies. By closing gaps in basic lifesaving knowledge, the initiative promotes timely care, reduces preventable emergencies, and supports safer and more responsive communities.', 1, '2026-07-22T21:50:28.472Z', '2026-07-24T13:10:04.777Z');
INSERT INTO faqs (question, answer, sort_order, created_at, updated_at) VALUES ('How can I join SER?', '<p>You can join by registering through our <a href="https://www.seresponse.org/community?tab=join" rel="noopener noreferrer" target="_blank">website </a>or contacting us via <a href="https://wa.me/254742435314" rel="noopener noreferrer" target="_blank">WhatsApp</a></p>', 2, '2026-07-22T21:50:28.472Z', '2026-08-10T11:30:42.854Z');
INSERT INTO faqs (question, answer, sort_order, created_at, updated_at) VALUES ('What training do members receive?', 'Members receive training in first aid, fire safety skills, Psychological First Aid, emergency preparedness, disaster response, and community safety. Training may include simulations, drills, and practical sessions depending on the event.', 3, '2026-07-22T21:50:28.472Z', '2026-07-24T13:13:48.579Z');
INSERT INTO faqs (question, answer, sort_order, created_at) VALUES ('Are there age restrictions to join?', 'No. SER welcomes people of all ages who want to contribute to safer communities. Some activities may be organized by age group for training purposes.', 4, '2026-07-22T21:50:28.472Z');
INSERT INTO projects (title, focus, description, link, link_text, created_at) VALUES ('ClickSafe Initiative', 'Cybersecurity & Online Safety', 'A youth-led program training students and communities on safe internet use, digital responsibility, and protection from online risks.', '/contact', 'Partner / Join', '2026-07-22T21:50:27.716Z');
INSERT INTO projects (title, focus, description, link, link_text, created_at) VALUES ('Emergency Drill Simulations', 'Preparedness & Response Practice', 'Practical emergency drills for Scouts and schools to build readiness for fire incidents, injuries, evacuations, and disaster scenarios.', '/events', 'See Events', '2026-07-22T21:50:27.716Z');
INSERT INTO projects (title, focus, description, link, link_text, created_at) VALUES ('First Aid Camps', 'Life-saving Skills', 'Hands-on first aid training sessions with demonstrations, practice, and community outreach to improve rapid response and confidence.', '/contact', 'Request Training', '2026-07-22T21:50:27.716Z');
INSERT INTO projects (title, focus, description, link, link_text, created_at) VALUES ('Environmental Restoration Drives', 'Community Resilience', 'Cleanup and restoration projects that reduce risk, protect public health, and support safer environments for communities.', '/community', 'Join Community', '2026-07-22T21:50:27.716Z');
INSERT INTO projects (title, focus, description, link, link_text, created_at) VALUES ('Community Safety Ambassadors', 'Awareness & Leadership', 'Training Scouts and volunteers to champion first aid awareness, safe practices, and emergency readiness in local communities.', '', '', '2026-07-22T21:50:27.716Z');
